  try {
    const orders = await db.order.findMany({
      take: 25,
      select: { id: true, amount: true, status: true, createdAt: true },
    });

    return NextResponse.json(orders, {
      headers: {
        // Micro-cache at CDN edge for 5 seconds to absorb thundering herds
